import { stripVTControlCharacters as strip, toUSVString as usv } from "node:util";
import * as util from "util";

export function reportTextUtilities() {
  console.log("identity", strip === util.stripVTControlCharacters, usv === util.toUSVString);
  for (const text of ["", "plain café 😀", "\u001b[31mred\u001b[0m", "\u009b1;32mgreen\u009b0m", "\u001b]0;title\u0007tail", "\u001b]8;;https://example.com\u001b\\link\u001b]8;;\u001b\\", "\u001b]0;title\u009ctail", "\u001b[?25lhide\u001b[?25h", "\u001b[", "\u001b]unterminated", "\u001b\\", "embedded\u0000\u001b[1mNUL"]) console.log("strip", JSON.stringify(strip(text)));
  for (const text of ["", "café 😀", "\ud800", "\udfff", "a\ud800z", "\ud800\ud800\udc00\udc00", "\ud83d\ude00", "\udc00\ud800", "\udbff\udfff"]) console.log("usv", JSON.stringify(usv(text)));
  for (const value of [undefined, null, 0, -0, 1.5, NaN, Infinity, true, false, 2n, Symbol("x"), {}, [], [1, 2], new String("boxed"), new Number(2), function sample() {}]) {
    try { console.log("strip-value", strip(value)); }
    catch (error) { console.log(error.name, error.code, error.message); }
    try { console.log("usv-value", usv(value)); }
    catch (error) { console.log(error.name, error.code, error.message); }
  }
  const calls = [];
  const exotic = { [Symbol.toPrimitive](hint) { calls.push(hint); return "\ud800"; } };
  console.log("exotic", JSON.stringify(usv(exotic)), calls.join(","));
  const ordinary = { toString() { calls.push("toString"); return {}; }, valueOf() { calls.push("valueOf"); return "\udfff"; } };
  console.log("ordinary", JSON.stringify(usv(ordinary)), calls.join(","));
  const sentinel = new Error("conversion failed");
  try { usv({ toString() { throw sentinel; } }); } catch (error) { console.log("throw-identity", error === sentinel); }
  try { usv({ [Symbol.toPrimitive]() { throw sentinel; } }); } catch (error) { console.log("exotic-throw-identity", error === sentinel); }
  try { usv({ [Symbol.toPrimitive]() { return Symbol("x"); } }); } catch (error) { console.log("symbol-result", error.name, error.message); }
  for (const method of [1, -0, NaN, Infinity, true, 2n, Symbol("x"), "bad", "a\nb", '"quoted"', {}, null, undefined]) {
    try { console.log("exotic-method", usv({ [Symbol.toPrimitive]: method })); }
    catch (error) { console.log("exotic-method", error.name, error.message); }
  }
  try { usv({ toString() { return {}; }, valueOf() { return {}; } }); } catch (error) { console.log("non-primitive", error.name, error.message); }
  try { usv({ [Symbol.toPrimitive]() { return {}; } }); } catch (error) { console.log("exotic-object", error.name, error.message); }
  try { strip(); } catch (error) { console.log("omitted", error.name, error.code, error.message); }
  console.log("omitted-usv", usv());
  // Exercise every control terminator and parameter class in the pinned matcher.
  let digest = 0;
  const bodies = ["", "[", "]", "[31", "[1;2", "]0;title", "]8;;https://x", ";x/y#&.:=?%@~_", "[?25", "[12345", "[;;", "(B", "abc;xyz", "abc;", "[]#;?"];
  for (const intro of ["\u001b", "\u009b"]) for (const body of bodies) {
    for (let code = 0; code < 160; code++) {
      const text = "前" + intro + body + String.fromCharCode(code) + "後";
      const result = strip(text);
      for (let i = 0; i < result.length; i++) digest = (digest * 31 + result.charCodeAt(i)) >>> 0;
    }
  }
  console.log("control-matrix", digest);
}
